// Basic usage with calculatePopupPosition
import { calculatePopupPosition } from '@/lib/designsystem/utils/popupPosition';

const handleOpenPopup = () => {
  const triggerElement = document.getElementById('trigger-button');
  const popupElement = document.getElementById('popup-content');

  if (triggerElement && popupElement) {
    const position = calculatePopupPosition(triggerElement, popupElement);
    Object.assign(popupElement.style, {
      position: 'absolute',
      left: `${position.x}px`,
      top: `${position.y}px`,
      transformOrigin: position.transformOrigin,
    });
  }
};
```

