```tsx
// React hook usage
import { useRef, useState } from 'react';
import { usePopupPosition } from '@/lib/designsystem/utils/popupPosition';

function DropdownMenu() {
  const [isOpen, setIsOpen] = useState(false);
  const triggerRef = useRef(null);
  const menuRef = useRef(null);

  const positionStyles = usePopupPosition(triggerRef, menuRef, {
    preferredPlacement: 'bottom',
    preferredAlignment: 'start',
  });

  return (
    <div>
      <button ref={triggerRef} onClick={() => setIsOpen(!isOpen)}>
        Open Menu
      </button>
      {isOpen && (
        <div ref={menuRef} style={positionStyles} className="dropdown-menu">
          {/* Menu items */}
        </div>
      )}
    </div>
  );
}
